SELECT coalesce(string_agg(concat_ws('|', source, table_generation, txn_or_batch_id, payload_digest, fence_shard, fence_generation::text, coalesce(segment_index::text, 'null'), coalesce(segment_count::text, 'null'), octet_length(segment_bitmap)::text, encode(segment_bitmap, 'hex'), target_commit_at::text, partial_txn::text, cross_table_consistent::text, txn_complete::text), E'\n' ORDER BY source, table_generation, txn_or_batch_id), '') FROM _oo.apply_receipts;
